"""The generated files of the repository and the text each one must have.

One place declares which file is derived from which source:

- docs/adr/README.md, from the ADR files as the adrs tool exports them;
- skills/README.md and .claude/skills/<name>/SKILL.md, from skills/<name>.md;
- tests/pending.toml, from the model's JSON export and the written tests.

`mise run generate` writes them; `mise run generate:check` fails when one is
out of date. Nothing here reads the text of the model: the verifications come
from the Pilot Implementation's export (tests/repository/sysml_model.py).
"""

import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "tests" / "repository"))

TASK = "mise run generate"


# ---- ADR index ----------------------------------------------------------


# One line per record: number, link, title and status, as adrs exports them.
ADR_LINE = (
    '.adrs | sort_by(.number)[] | "- [\\(("0000" + (.number | tostring))[-4:])]"'
    ' + "(\\(.path | split("/") | last)) \\(.title) (\\(.status | ascii_downcase))"'
)


def adr_index():
    exported = subprocess.run(
        ["adrs", "export", "json"], cwd=ROOT, check=True, capture_output=True, text=True
    ).stdout
    entries = subprocess.run(
        ["jq", "-r", ADR_LINE],
        input=exported,
        check=True,
        capture_output=True,
        text=True,
    ).stdout.splitlines()
    return (
        f"<!-- Generated by `{TASK}` from the ADR files. Do not edit. -->\n\n"
        "# Architecture decision records\n\n"
        "An ADR records a decision, in the MADR 4.0.0 format, with the options\n"
        'considered and why each lost. An ADR in the status "proposed" describes\n'
        "the intended system, not the present one: what is built and verified is\n"
        "told by the tests and by `tests/pending.toml`.\n\n" + "\n".join(entries) + "\n"
    )


# ---- Skills -------------------------------------------------------------


def front_matter(path):
    """`name` and `description` of a skill document; the body follows."""
    match = re.match(r"---\n(.*?)\n---\n", path.read_text(), re.DOTALL)
    assert match, f"{path.name}: no front matter"
    fields = {}
    for line in match[1].splitlines():
        key, _, value = line.partition(": ")
        fields[key] = json.loads(value) if value.startswith('"') else value
    assert set(fields) == {"name", "description"}, f"{path.name}: {sorted(fields)}"
    assert fields["name"] == path.stem, f"{path.name}: name differs from file name"
    return fields


def skills():
    paths = sorted((ROOT / "skills").glob("infrastructure-*.md"))
    return [front_matter(p) for p in paths]


def skills_index():
    lines = "\n".join(
        f"- [`{s['name']}`]({s['name']}.md): {s['description']}" for s in skills()
    )
    return (
        f"<!-- Generated by `{TASK}` from the skill files. Do not edit. -->\n\n"
        "# Skills\n\n"
        "Criteria and methods of this repository as skill documents for any AI "
        "coding agent, and for a person. Load the one that matches the work "
        "before you start.\n\n"
        f"{lines}\n\n"
        "The content lives here, in plain Markdown with no vendor syntax. For "
        "Claude Code, `.claude/skills/<name>/SKILL.md` is only a thin pointer: "
        "frontmatter that says when to use the skill, then an import of the file "
        "here. Another agent vendor wires its own pointers the same way, never "
        "copying the content. The name and the description are written once, at "
        "the top of each skill file; this index and the pointers are generated "
        "from them.\n"
    )


def skill_pointer(skill):
    name = skill["name"]
    return (
        "---\n"
        f"# Generated by `{TASK}` from skills/{name}.md. Do not edit.\n"
        f"name: {name}\n"
        f"description: {json.dumps(skill['description'], ensure_ascii=False)}\n"
        "---\n\n"
        f"@../../../skills/{name}.md\n"
        f"If the line above was not expanded, read `skills/{name}.md` in the "
        "repository root and follow it.\n"
    )


# ---- tests/pending.toml -------------------------------------------------


def _order(name):
    match = re.match(r"test_R(\d+)(?:_(\d+)(?=_))?", name)
    return int(match[1]), int(match[2] or 0), name


def render_pending(verifications, tests):
    """The verifications of the model that have no written test."""
    pending = sorted(set(verifications) - set(tests), key=_order)
    items = "".join(f'  "{name}",\n' for name in pending)
    body = f"pending = [\n{items}]\n" if pending else "pending = []\n"
    return (
        f"# Generated by `{TASK}`. Do not edit.\n"
        "#\n"
        "# Verifications in model/infrastructure.sysml whose test is not written\n"
        "# yet, computed from the model's JSON export and the names of the tests.\n"
        "#\n"
        "# This list shrinks as tests are written; it grows only when a requirement\n"
        "# is added to the model. tests/repository/test_traceability.py fails when a\n"
        "# verification is neither tested nor listed here, and when a test listed\n"
        "# here has been written.\n" + body
    )


def pending_toml():
    import sysml_model  # imported here: the export is slow, so only when needed

    model = sysml_model.export_model()
    return render_pending(
        sysml_model.verifications(model), sysml_model.names_of_tests()
    )


# ---- All of them --------------------------------------------------------


def outputs():
    """Every generated file: path relative to the root, and its exact text."""
    files = {
        "docs/adr/README.md": adr_index(),
        "skills/README.md": skills_index(),
        "tests/pending.toml": pending_toml(),
    }
    for skill in skills():
        files[f".claude/skills/{skill['name']}/SKILL.md"] = skill_pointer(skill)
    return files
